import Stripe from 'npm:stripe@17';

const stripe = new Stripe(Deno.env.get('STRIPE_SECRET_KEY')!);

Deno.serve(async (req) => {
  const signature = req.headers.get('stripe-signature')!;
  const event = await stripe.webhooks.constructEventAsync(await req.text(), signature, Deno.env.get('STRIPE_WEBHOOK_SECRET')!);
  console.log('stripe event', event.type);
  return new Response(JSON.stringify({ received: true }), { headers: { 'Content-Type': 'application/json' } });
});

Deno.serve(async (req) => {
  const { order_id } = await req.json();
  // Sends the order confirmation through the transactional email provider.
  return new Response(JSON.stringify({ queued: order_id }), { headers: { 'Content-Type': 'application/json' } });
});
